import{_ as e,o as d,c as o,a3 as a}from"./chunks/framework.BLaSdaBb.js";const u=JSON.parse('{"title":"常用组件","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/components.md","filePath":"frontend/components.md","lastUpdated":1786258579000}'),c={name:"frontend/components.md"};function r(i,t,n,s,l,h){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="常用组件" tabindex="-1">常用组件 <a class="header-anchor" href="#常用组件" aria-label="Permalink to &quot;常用组件&quot;">​</a></h1><p>除 <a href="./schema-page">Schema 页面引擎</a> 之外的公共组件与全局挂件，按用途分组速查。组件源码在 <code>packages/components/</code>、<code>packages/layouts/</code> 与 <code>packages/iconify/</code>。</p><h2 id="编辑器" tabindex="-1">编辑器 <a class="header-anchor" href="#编辑器" aria-label="Permalink to &quot;编辑器&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>底层</th><th>用途</th></tr></thead><tbody><tr><td><code>RichTextEditor.vue</code></td><td>Tiptap</td><td>富文本。含 Link / Image / Highlight / TextAlign / Underline 等扩展</td></tr><tr><td><code>MdEditor.vue</code></td><td>md-editor-v3</td><td>Markdown</td></tr><tr><td><code>JsonEditor.vue</code></td><td>vue3-ts-jsoneditor</td><td>JSON 编辑与查看</td></tr></tbody></table><p>通知公告正文用 Markdown 编辑器（文件库的 Markdown 预览也复用它）；富文本与 JSON 编辑器目前只在编辑器演示页 <code>packages/views/_core/editor-demo/</code> 使用。三者都以 <code>defineAsyncComponent</code> 懒加载，不进主依赖图。</p><h2 id="表单增强" tabindex="-1">表单增强 <a class="header-anchor" href="#表单增强" aria-label="Permalink to &quot;表单增强&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>用途</th></tr></thead><tbody><tr><td><code>CronExpression.vue</code></td><td>Cron 表达式：输入框 + 可视化弹窗，不必手写表达式。<a href="./../backend/scheduling">任务调度</a>页在用</td></tr><tr><td><code>XEditModal</code> + <code>xh-edit-form-grid</code></td><td><strong>统一的新增/编辑弹窗外壳</strong>：两列布局、10px 间距、11px 标签、无反馈占位，跨列用 <code>xh-span-2</code></td></tr><tr><td><code>IconPicker</code></td><td>图标选择器，可按需懒加载图标集</td></tr><tr><td><code>XLogoUpload</code>（<code>src/components/LogoUpload.vue</code>） / <code>XUserAvatar</code></td><td>图片上传与头像展示（内置 URL 解析与首字母兜底）</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">新增/编辑弹窗一律用 <code>XEditModal</code></p><p>全仓已统一，<strong>不要再手写 <code>NModal</code> 外壳</strong>。统一外壳保证了弹窗尺寸、间距、标签宽度、按钮位置在所有页面一致，也让后续调整只改一处。</p></div><h2 id="消息中心-ui" tabindex="-1">消息中心 UI <a class="header-anchor" href="#消息中心-ui" aria-label="Permalink to &quot;消息中心 UI&quot;">​</a></h2><p>三个层次（<code>~/layouts/basic/</code> 与 <code>src/views/message/</code>）：</p><table tabindex="0"><thead><tr><th>层</th><th>组件</th><th>行为</th></tr></thead><tbody><tr><td><strong>顶部横幅</strong></td><td><code>NotificationBanner.vue</code> + <code>use-banner-notices.ts</code></td><td>数据由服务端按有效期、角色/部门定向过滤后下发；按严重度 + 优先级取前 3 条轮播（5s，悬停暂停）。关闭记忆按公告 id 存 localStorage（30 天清理），后台重发即新 id、自然重现</td></tr><tr><td><strong>强制阅读 + 登录弹窗</strong></td><td><code>NotificationGate.vue</code></td><td>未读必读公告以遮罩拦截、逐条「我已阅读」（最高优先级）；清空后再逐条弹出普通登录后公告</td></tr><tr><td><strong>通知中心页</strong></td><td><code>src/views/message/notification/</code></td><td>发布、定向、统计等运营闭环</td></tr></tbody></table><p>业务设计见 <a href="./../backend/messaging">后端手册 · 消息通知</a>。</p><h2 id="全局挂件" tabindex="-1">全局挂件 <a class="header-anchor" href="#全局挂件" aria-label="Permalink to &quot;全局挂件&quot;">​</a></h2><p>挂在 <code>App.vue</code> 上、全应用生效：</p><table tabindex="0"><thead><tr><th>组件</th><th>说明</th></tr></thead><tbody><tr><td><code>LockScreen.vue</code></td><td>锁屏遮罩。后端返回 <strong><code>423</code></strong> 时拉起——身份仍有效，解锁而非重新登录</td></tr><tr><td><code>AppWatermark.vue</code></td><td>水印</td></tr><tr><td><code>DynamicIsland.vue</code></td><td>灵动岛：全局操作反馈（进行中/成功/失败、进度环、岛内按钮、服务端任务进度）</td></tr></tbody></table><p>全局搜索（<code>AppGlobalSearch.vue</code>）挂在布局顶栏工具条上，<code>Ctrl/Cmd + K</code> 唤起。</p><h2 id="文件与图片" tabindex="-1">文件与图片 <a class="header-anchor" href="#文件与图片" aria-label="Permalink to &quot;文件与图片&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>说明</th></tr></thead><tbody><tr><td><code>useAvatarUrl</code></td><td>头像 URL 解析（fileId → 预签名 URL，直链原样；空值/失败返回空串，由 <code>XUserAvatar</code> 首字母兜底）</td></tr><tr><td><code>toAbsoluteFileUrl</code></td><td>文件 URL 绝对化</td></tr><tr><td><code>SchemaImportDialog</code></td><td>CSV 导入对话框：模板下载 → 解析 → 预校验 → 逐行创建</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">本地存储的 URL 是根相对路径</p><p>本地存储返回 <code>/uploads/...</code>。前后端同源没问题，<strong>线上不同源时必须拼上 <code>VITE_API_BASE_URL</code> 的 origin</strong>，否则浏览器拿前端域名去请求而 404。上面两个工具已处理，自己拼 URL 时别忘了。</p></div><h2 id="图编辑" tabindex="-1">图编辑 <a class="header-anchor" href="#图编辑" aria-label="Permalink to &quot;图编辑&quot;">​</a></h2><p><code>packages/diagram</code> 基于 AntV X6 封装通用图编辑能力（工作流设计器在用）。应用侧只依赖本包导出的 <code>XDiagram</code> / <code>DiagramApi</code> / <code>DiagramData</code> / <code>registerVueShape</code>，不直接依赖 <code>@antv/x6</code>。</p><h2 id="布局" tabindex="-1">布局 <a class="header-anchor" href="#布局" aria-label="Permalink to &quot;布局&quot;">​</a></h2><p><code>packages/layouts/</code> 提供整套布局外壳：侧边栏、顶栏、标签页、内容区、页脚。</p><div class="tip custom-block"><p class="custom-block-title">整屏页用 <code>h-full</code> 或 <code>XPageShell</code></p><p>布局根是定高的、内容容器内部滚动（滚动源不是 <code>window</code>）。需要吸顶/吸底的整屏页直接用 <code>h-full</code> 或 <code>XPageShell</code> 即可，<strong>不要再写 per-page 的 JS 定高 hack</strong>。</p></div><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./schema-page">Schema 驱动页面</a>：列表页引擎</li><li><a href="./theme">布局与主题</a>：布局配置与主题定制</li><li><a href="./realtime">实时通信</a>：消息中心的推送通道</li><li><a href="./icon">字体图标</a>：图标用法与离线模式限制</li></ul>',26)])])}const b=e(c,[["render",r]]);export{u as __pageData,b as default};
